const snapshots = new Map();
const store = { read, write };

export async function loadSnapshot(name) {
  if (snapshots.has(name)) return snapshots.get(name);
  const value = await store.read(name);
  snapshots.set(name, value);
  return value;
}

export async function updateSnapshot(name, next) {
  await store.write(name, next);
  snapshots.set(name, next);
  return next;
}

export function clearSnapshot(name) {
  snapshots.delete(name);
}

